svg1 = '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="700" height="260" rx="14" fill="#f8fafc" stroke="#2563eb" stroke-width="2"/><rect x="18" y="14" width="664" height="36" rx="8" fill="#2563eb"/><text x="350" y="37" fill="#ffffff" font-size="15" font-weight="bold" text-anchor="middle">KİNETİK VE POTANSİYEL ENERJİ KARŞILAŞTIRMASI (FB.7.2.2)</text><rect x="24" y="62" width="206" height="182" rx="10" fill="#eff6ff" stroke="#1d4ed8" stroke-width="1.5"/><text x="127" y="84" fill="#1e3a8a" font-size="13" font-weight="bold" text-anchor="middle">KİNETİK ENERJİ (Ek)</text><text x="127" y="108" fill="#1e293b" font-size="11" text-anchor="middle">• Kaynağı: Cismin HAREKETİ</text><text x="127" y="130" fill="#1e293b" font-size="11" text-anchor="middle">• Değişken 1: Kütle (m) ile</text><text x="127" y="146" fill="#1d4ed8" font-size="11" font-weight="bold" text-anchor="middle">doğru orantılıdır.</text><text x="127" y="170" fill="#1e293b" font-size="11" text-anchor="middle">• Değişken 2: Sürat (v) ile</text><text x="127" y="186" fill="#1d4ed8" font-size="11" font-weight="bold" text-anchor="middle">doğru orantılıdır.</text><text x="127" y="214" fill="#334155" font-size="10.5" text-anchor="middle">Örnek: Koşan çocuk, akan su</text><rect x="246" y="62" width="208" height="182" rx="10" fill="#f0fdf4" stroke="#15803d" stroke-width="1.5"/><text x="350" y="84" fill="#14532d" font-size="13" font-weight="bold" text-anchor="middle">BENZER ÖZELLİKLER</text><text x="350" y="112" fill="#1e293b" font-size="11" text-anchor="middle">• İkisi de İŞ YAPABİLME</text><text x="350" y="128" fill="#1e293b" font-size="11" text-anchor="middle">yeteneğidir (enerji çeşididir).</text><text x="350" y="152" fill="#1e293b" font-size="11" text-anchor="middle">• Birimleri JOULE (J)’dür.</text><text x="350" y="176" fill="#1e293b" font-size="11" text-anchor="middle">• Birbirine dönüşebilirler.</text><text x="350" y="200" fill="#15803d" font-size="11" font-weight="bold" text-anchor="middle">• Toplamları MEKANİK</text><text x="350" y="216" fill="#15803d" font-size="11" font-weight="bold" text-anchor="middle">ENERJİYİ (Em = Ek + Ep) verir.</text><rect x="470" y="62" width="206" height="182" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/><text x="573" y="84" fill="#92400e" font-size="13" font-weight="bold" text-anchor="middle">POTANSİYEL ENERJİ (Ep)</text><text x="573" y="108" fill="#1e293b" font-size="11" text-anchor="middle">• Kaynağı: KONUM / DURUM</text><text x="573" y="132" fill="#92400e" font-size="11" font-weight="bold" text-anchor="middle">1) Çekim Potansiyeli:</text><text x="573" y="148" fill="#1e293b" font-size="10.5" text-anchor="middle">Ağırlık (G) ve Yükseklik (h)</text><text x="573" y="172" fill="#92400e" font-size="11" font-weight="bold" text-anchor="middle">2) Esneklik Potansiyeli:</text><text x="573" y="188" fill="#1e293b" font-size="10.5" text-anchor="middle">Yay cinsi ve sıkışma/gerilme</text><text x="573" y="214" fill="#334155" font-size="10.5" text-anchor="middle">Örnek: Dalda elma, gerili yay</text></svg>'
svg2 = '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="700" height="260" rx="14" fill="#fffbeb" stroke="#d97706" stroke-width="2"/><rect x="18" y="14" width="664" height="36" rx="8" fill="#d97706"/><text x="350" y="37" fill="#ffffff" font-size="15" font-weight="bold" text-anchor="middle">SARKAÇTA ENERJİ DÖNÜŞÜMÜ VE ENERJİNİN KORUNUMU (FB.7.2.3)</text><line x1="210" y1="60" x2="210" y2="68" stroke="#334155" stroke-width="3"/><rect x="160" y="54" width="100" height="8" fill="#475569"/><line x1="210" y1="62" x2="105" y2="145" stroke="#64748b" stroke-width="2" stroke-dasharray="4 3"/><line x1="210" y1="62" x2="210" y2="195" stroke="#1e293b" stroke-width="2.5"/><line x1="210" y1="62" x2="315" y2="145" stroke="#64748b" stroke-width="2" stroke-dasharray="4 3"/><circle cx="105" cy="145" r="18" fill="#f59e0b" stroke="#92400e" stroke-width="2"/><text x="105" y="150" fill="#ffffff" font-size="12" font-weight="bold" text-anchor="middle">K</text><circle cx="210" cy="195" r="18" fill="#2563eb" stroke="#1e3a8a" stroke-width="2"/><text x="210" y="200" fill="#ffffff" font-size="12" font-weight="bold" text-anchor="middle">L</text><circle cx="315" cy="145" r="18" fill="#f59e0b" stroke="#92400e" stroke-width="2"/><text x="315" y="150" fill="#ffffff" font-size="12" font-weight="bold" text-anchor="middle">M</text><text x="85" y="182" fill="#92400e" font-size="10.5" font-weight="bold" text-anchor="middle">K (En Üst): Ep Maks, Ek = 0</text><text x="210" y="232" fill="#1e3a8a" font-size="10.5" font-weight="bold" text-anchor="middle">L (En Alt): Ek Maks, Ep Min</text><text x="335" y="182" fill="#92400e" font-size="10.5" font-weight="bold" text-anchor="middle">M (En Üst): Ep Maks, Ek = 0</text><rect x="415" y="64" width="265" height="180" rx="10" fill="#ffffff" stroke="#b45309" stroke-width="1.5"/><text x="547" y="86" fill="#92400e" font-size="12.5" font-weight="bold" text-anchor="middle">ENERJİNİN KORUNUMU İLKESİ</text><text x="547" y="110" fill="#1e293b" font-size="11" text-anchor="middle">• Sürtünmesiz ortamda:</text><text x="547" y="128" fill="#15803d" font-size="11.5" font-weight="bold" text-anchor="middle">Emekanik = Ek + Ep = SABİT</text><text x="547" y="152" fill="#1e293b" font-size="11" text-anchor="middle">• K → L inerken: Ep azalır, Ek artar.</text><text x="547" y="172" fill="#1e293b" font-size="11" text-anchor="middle">• L → M çıkarken: Ek azalır, Ep artar.</text><text x="547" y="198" fill="#dc2626" font-size="10.5" font-weight="bold" text-anchor="middle">• Sürtünmeli ortamda mekanik enerji</text><text x="547" y="214" fill="#dc2626" font-size="10.5" font-weight="bold" text-anchor="middle">azalsa da TOPLAM ENERJİ KORUNUR</text><text x="547" y="230" fill="#334155" font-size="10" text-anchor="middle">(azalan kısım ısı enerjisine dönüşür).</text></svg>'
svg3 = '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="700" height="260" rx="14" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/><rect x="18" y="14" width="664" height="36" rx="8" fill="#16a34a"/><text x="350" y="37" fill="#ffffff" font-size="15" font-weight="bold" text-anchor="middle">SÜRTÜNME KUVVETİ: HAVA DİRENCİ VE SU DİRENCİ</text><rect x="24" y="62" width="316" height="182" rx="10" fill="#ffffff" stroke="#0284c7" stroke-width="1.5"/><text x="182" y="84" fill="#0369a1" font-size="13" font-weight="bold" text-anchor="middle">HAVA DİRENCİ (Hava Sürtünmesi)</text><text x="182" y="108" fill="#1e293b" font-size="11" text-anchor="middle">• Havadaki cisimlerin hareketini zorlaştırır.</text><text x="182" y="130" fill="#15803d" font-size="11" font-weight="bold" text-anchor="middle">• Azaltmak için (Sürati artırmak):</text><text x="182" y="146" fill="#334155" font-size="10.5" text-anchor="middle">Uçak, hızlı tren ve yarış araçlarının burnu</text><text x="182" y="162" fill="#334155" font-size="10.5" text-anchor="middle">sivri (aerodinamik) yapılır; kuşlar V uçuşu yapar.</text><text x="182" y="186" fill="#b45309" font-size="11" font-weight="bold" text-anchor="middle">• Artırmak için (Güvenli iniş):</text><text x="182" y="202" fill="#334155" font-size="10.5" text-anchor="middle">Paraşüt yüzey alanı geniş tasarlanır.</text><rect x="358" y="62" width="318" height="182" rx="10" fill="#ffffff" stroke="#0f766e" stroke-width="1.5"/><text x="517" y="84" fill="#0f766e" font-size="13" font-weight="bold" text-anchor="middle">SU DİRENCİ (Su Sürtünmesi)</text><text x="517" y="108" fill="#1e293b" font-size="11" text-anchor="middle">• Suda hareket eden cisimlere ters yönde etki eder.</text><text x="517" y="130" fill="#15803d" font-size="11" font-weight="bold" text-anchor="middle">• Azaltmak için (Kolay yüzme/seyir):</text><text x="517" y="146" fill="#334155" font-size="10.5" text-anchor="middle">Gemilerin ön kısmı V şeklinde tasarlanır,</text><text x="517" y="162" fill="#334155" font-size="10.5" text-anchor="middle">balıkların vücudu kaygan pullu ve mekik biçimlidir,</text><text x="517" y="178" fill="#334155" font-size="10.5" text-anchor="middle">yüzücüler suya paralel dalış yapar ve bone takar.</text><text x="517" y="206" fill="#dc2626" font-size="11" font-weight="bold" text-anchor="middle">Not: Su direnci hava direncinden daha büyüktür!</text></svg>'

